from typing import List

def get_gcd(numbers: List[int]) -> int:
    """
    Calculate the greatest common divisor (GCD) of a list of integers.

    Parameters:
    numbers (List[int]): A list of integers.

    Returns:
    int: The greatest common divisor of all integers in the list.
    """
    if not numbers:
        raise ValueError('Input list must contain at least one integer.')
    current_gcd = 0
    for num in numbers:
        current_gcd = gcd(current_gcd, num)
    return abs(current_gcd)

