def compute_Last_Digit(a: int, b: int) -> int:
    """
    Given integers a and b, find the digit that corresponds to the division of factorial(b) by factorial(a).
    That is, compute (b! / a!) and return the last digit of this result.

    Since:
      b! / a! = (a+1) * (a+2) * ... * b

    We can compute the last digit of the product of the integers from a+1 to b.

    Parameters:
    a (int): the divisor factorial parameter (a!)
    b (int): the dividend factorial parameter (b!)

    Returns:
    int: the last digit of (b! / a!)
    """
    if a > b:
        return 1
    if a == b:
        return 1
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = last_digit * (x % 10) % 10
        if last_digit == 0:
            break
    return last_digit

