def Find_Min_Length(sublists):
    """
    Returns the length of the shortest sublist within the given list of sublists.

    Args:
        sublists (list of lists): A list containing sublists whose lengths are to be compared.

    Returns:
        int: The length of the shortest sublist. Returns 0 if the input list is empty or contains no sublists.
    """
    if not sublists:
        return 0
    filtered_sublists = [s for s in sublists if isinstance(s, list)]
    if not filtered_sublists:
        return 0
    return min((len(s) for s in filtered_sublists))

