def next_smallest_palindrome(num: int) -> int:
    """
    Find the next smallest palindrome strictly greater than the given number.

    For single-digit inputs, return the next palindrome directly (which is 11 if input is 9).

    Args:
        num (int): Input number.

    Returns:
        int: The next smallest palindrome greater than num.
    """

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]
    if 0 <= num <= 8:
        return num + 1
    if num == 9:
        return 11
    candidate = num + 1
    while True:
        if is_palindrome(candidate):
            return candidate
        candidate += 1

