from typing import Union, Tuple

def find_solution(a: int, b: int, n: int) -> Union[Tuple[str, int, str, int], str]:
    """
    Find non-negative integers x and y satisfying a*x + b*y = n,
    with x minimal among all such solutions.

    Returns:
        ('x = ', x, ', y = ', y) if solution exists,
        or 'No solution' if none exists.

    Uses the Extended Euclidean Algorithm and adjusts solutions
    to ensure non-negative x and y with minimal x.
    """

    def extended_gcd(x: int, y: int) -> Tuple[int, int, int]:
        if y == 0:
            return (x, 1, 0)
        else:
            gcd, x1, y1 = extended_gcd(y, x % y)
            return (gcd, y1, x1 - x // y * y1)
    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return 'No solution'
    factor = n // gcd
    x0 *= factor
    y0 *= factor
    b_div = b // gcd
    a_div = a // gcd
    import math
    t_min = math.ceil(-x0 / b_div) if b_div != 0 else 0
    t_max = math.floor(y0 / a_div) if a_div != 0 else 0
    if t_min > t_max:
        return 'No solution'
    t = t_min
    x = x0 + t * b_div
    y = y0 - t * a_div
    if x < 0 or y < 0:
        return 'No solution'
    return ('x = ', x, ', y = ', y)

