from typing import Tuple

def find_exponentio(base: Tuple[int, ...], exponent: Tuple[int, ...]) -> Tuple[int, ...]:
    """
    Perform exponentiation on two tuples element-wise.
    The exponentiation is done by raising each element in `base` to the power of the respective element in `exponent`.
    If the tuples have different lengths, the operation is performed up to the length of the shorter tuple.

    Args:
        base (Tuple[int, ...]): The base tuple containing integers.
        exponent (Tuple[int, ...]): The exponent tuple containing integers.

    Returns:
        Tuple[int, ...]: A tuple where each element is base[i] ** exponent[i].
    """
    length = min(len(base), len(exponent))
    return tuple((base[i] ** exponent[i] for i in range(length)))

