def get_total_number_of_sequences(n: int, m: int) -> int:
    """
    Returns the number of possible sequences of length n such that:
    - Each element is a positive integer between 1 and m (inclusive).
    - Each next element is greater than or equal to twice the previous element.

    Sequences may start with any element from 1 to m.

    Args:
        n (int): length of the sequence
        m (int): maximum allowed element value

    Returns:
        int: number of sequences satisfying the doubling condition with elements ≤ m,
             or 0 if n <= 0 or if no such sequences can be formed.
    """
    if n <= 0 or m <= 0:
        return 0
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(pos: int, val: int) -> int:
        if pos == n:
            return 1
        total = 0
        start_next = val * 2
        if start_next > m:
            return 0
        for next_val in range(start_next, m + 1):
            total += count_sequences(pos + 1, next_val)
        return total
    total_count = 0
    for start_val in range(1, m + 1):
        total_count += count_sequences(1, start_val)
    return total_count

