from typing import List

def permute_string(s: str) -> None:
    """
    Print all unique permutations of the given string, excluding duplicates.

    Args:
        s (str): The input string to permute.

    Prints:
        Each unique permutation on its own line.
    """
    chars = sorted(s)
    used = [False] * len(s)

    def backtrack(path: List[str]) -> None:
        if len(path) == len(chars):
            print(''.join(path))
            return
        for i in range(len(chars)):
            if used[i]:
                continue
            if i > 0 and chars[i] == chars[i - 1] and (not used[i - 1]):
                continue
            used[i] = True
            path.append(chars[i])
            backtrack(path)
            path.pop()
            used[i] = False
    backtrack([])

