from typing import List

def odd_length_sum(arr: List[int]) -> int:
    """
    Return the sum of all odd length subarrays of the input array.

    Parameters:
    arr (List[int]): The input list of integers.

    Returns:
    int: The sum of all odd length subarrays.
    """
    total_sum = 0
    n = len(arr)
    for length in range(1, n + 1, 2):
        for start in range(n - length + 1):
            subarray = arr[start:start + length]
            total_sum += sum(subarray)
    return total_sum

