def lcm(a: int, b: int) -> int:
    """
    Calculate the Least Common Multiple (LCM) of two integers.

    Args:
        a (int): First integer.
        b (int): Second integer.

    Returns:
        int: The LCM of a and b, or 0 if either input is zero.
    """

    def gcd(x: int, y: int) -> int:
        while y:
            x, y = (y, x % y)
        return abs(x)
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

