def compute_Last_Digit(a: int, b: int) -> int:
    """
    Given integers a and b, where factorial(a) divides factorial(b),
    find the last digit of the value factorial(b) // factorial(a).

    factorial(b) // factorial(a) = (a+1) * (a+2) * ... * b

    The function returns the last digit of this product.

    Assumes a <= b; if not, raises a ValueError.
    """
    if a > b:
        raise ValueError('Invalid input: a must be less than or equal to b.')
    if a == b:
        return 1
    product = 1
    for num in range(a + 1, b + 1):
        product *= num
        product %= 10
    return product

