    if a == 0 and b == 0:
        return 'No solution'
    if a == 0:
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return 'No solution'
    if b == 0:
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return 'No solution'
    candidate_solutions = []
    for y in range(0, 101):
        numerator = n - b * y
        if numerator % a == 0:
            x = numerator // a
            if x >= 0:
                candidate_solutions.append((x, y))
    if not candidate_solutions:
        return 'No solution'
    candidate_solutions.sort(key=lambda pair: pair[0])
    return candidate_solutions[0]

