def next_power_of_2(n: int) -> int:
    """
    Find the minimum power of 2 greater than or equal to n.

    Parameters:
    n (int): The input integer (assumed to be non-negative).

    Returns:
    int: The smallest power of 2 greater than or equal to n.
         If n <= 1, returns 1.
    """
    if n <= 1:
        return 1
    if n & n - 1 == 0:
        return n
    power = 1
    while power < n:
