from typing import List, Tuple, Any, Union

def repeat_tuples(items: Union[List[Tuple[Any, ...]], Tuple[Any, ...]], n: int) -> Union[List[Tuple[Any, ...]], Tuple[Tuple[Any, ...], ...]]:
    """
    Generate a collection by duplicating grouped items a specific number of times.

    Parameters:
    items (Union[List[Tuple[Any, ...]], Tuple[Any, ...]]): Either a list of tuples representing grouped items,
        or a single tuple.
    n (int): The number of times to duplicate each tuple group.

    Returns:
    Union[List[Tuple[Any, ...]], Tuple[Tuple[Any, ...], ...]]: 
        - If input is a list of tuples, returns a list containing each tuple duplicated n times in sequence.
        - If input is a single tuple, returns a tuple containing the single tuple duplicated n times.
        - If n is zero or input is empty, returns an empty list or empty tuple accordingly.

    Examples:
    >>> repeat_tuples([(1, 2), (3, 4)], 3)
    [(1, 2), (1, 2), (1, 2), (3, 4), (3, 4), (3, 4)]

    >>> repeat_tuples(('a', 'b'), 2)
    (('a', 'b'), ('a', 'b'))

    >>> repeat_tuples([], 2)
    []

    >>> repeat_tuples(('a',), 0)
    ()
    """
    if n == 0:
        if isinstance(items, list):
            return []
        elif isinstance(items, tuple):
            return ()
        else:
            return type(items)()
    if isinstance(items, list):
        result = []
        for group in items:
            result.extend([group] * n)
        return result
    elif isinstance(items, tuple):
        return tuple([items] * n)
    else:
        raise TypeError('Input must be either a list of tuples or a single tuple.')

