def smallest_missing(arr: Sequence[int], start: Optional[int]=None, end: Optional[int]=None) -> int:
    """
    Identify the lowest absent value within an ordered collection.

    Given a sorted collection of integers, find the smallest non-negative integer
    that is not present in the specified subrange of the collection.

    Args:
        arr: A sequence of sorted integers (ascending order).
        start: Optional start index of the subrange to consider (inclusive).
        end: Optional end index of the subrange to consider (inclusive).

    Returns:
        The smallest non-negative integer not present in the specified subrange.
    """
    if start is None:
        start = 0
    if end is None:
        end = len(arr) - 1
    missing = 0
    for i in range(start, end + 1):
        num = arr[i]
        if num == missing:
            missing += 1
        elif num > missing:
            break
    return missing

