T = TypeVar('T')

def find_Max(seq: Sequence[T], start: int, end: int) -> Optional[T]:
    """
    Select the greatest entry from a shifted sequence within the given index range [start, end].

    The sequence is assumed to be originally sorted in ascending order and then rotated at some pivot.
    The elements are assumed to be unique.

    If the sub-sequence defined by start and end is empty (start > end), returns None.

    Args:
        seq: A sequence of comparable items.
        start: Start index of the sub-sequence to consider.
        end: End index of the sub-sequence to consider.

    Returns:
        The greatest entry in seq[start:end+1], or None if empty.
    """
    if start > end:
        return None
    if seq[start] < seq[end]:
        return seq[end]
    left, right = (start, end)
    while left < right:
        mid = (left + right) // 2
        if seq[mid] > seq[right]:
            left = mid + 1
        else:
            right = mid
    return seq[left - 1] if left > start else seq[end]

