def recur_gcd(a: int, b: int) -> int:
    """
    Calculate the Greatest Common Divisor (GCD) of two integers using a repeated process (Euclidean algorithm).

    Args:
        a (int): First integer.
        b (int): Second integer.

    Returns:
        int: The GCD of the two input integers, always non-negative.
    """
    if b == 0:
        return abs(a)
    else:
        return recur_gcd(b, a % b)
