from typing import Tuple

def str_to_tuple(s: str) -> Tuple[int, ...]:
    """
    Convert a string of grouped numbers separated by commas into a tuple of integers.
    Supports inputs with or without grouping brackets (parentheses or square brackets).
    Examples:
    >>> str_to_tuple("1,2,3")
    (1, 2, 3)
    >>> str_to_tuple("(1,2,3)")
    (1, 2, 3)
    >>> str_to_tuple("[10, 20, 30]")
    (10, 20, 30)
    >>> str_to_tuple("7")
    (7,)
    >>> str_to_tuple("")
    ()

    Args:
        s: a string containing numbers separated by commas, optionally grouped inside () or [].

    Returns:
        A tuple of integers parsed from the input string.
    """
    if not s:
        return ()
    s = s.strip()
    if s.startswith('(') and s.endswith(')') or (s.startswith('[') and s.endswith(']')):
        s = s[1:-1].strip()
    if not s:
        return ()
    return tuple((int(x.strip()) for x in s.split(',')))

