def get_noOfways(n, r=None):
    """
    Return the nth value of a sequence defined as:
    - 0 for n=0
    - 1 for n=1
    - for n≥2, sum of the two previous values

    The argument r is ignored since this function computes the nth sequence value.

    Args:
        n (int): The position in the sequence (0-based).
        r: Ignored.

    Returns:
        int: The nth value of the sequence.

    Raises:
        TypeError: If n is not an integer.
        ValueError: If n is negative.
    """
    if not isinstance(n, int):
        raise TypeError('n must be an integer')
    if n < 0:
        raise ValueError('n must be non-negative')
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = (0, 1)
    for _ in range(2, n + 1):
        a, b = (b, a + b)
    return b

