def compute_Last_Digit(a: int, b: int) -> int:
    """
    Compute the last digit of a! / b! under the paradoxical interpretation:
    - If a == b, return 1.
    - If a > b, return the last digit of the product of integers from b+1 to a.
    - If a < b:
       * If difference (b - a) >= 5, return 0.
       * Else return the last digit of the product of integers from a+1 to b.
    """
    if a == b:
        return 1
    elif a > b:
        product_last_digit = 1
        for x in range(b + 1, a + 1):
            product_last_digit = product_last_digit * (x % 10) % 10
        return product_last_digit
    else:
        diff = b - a
        if diff >= 5:
            return 0
        product_last_digit = 1
        for x in range(a + 1, b + 1):
            product_last_digit = product_last_digit * (x % 10) % 10
        return product_last_digit

