from typing import Optional, Tuple

def find_solution(a: int, b: int, n: int) -> Optional[Tuple[int, int]]:
    """
    Find non-negative integers x and y such that a*x + b*y = n.
    Returns a tuple (x, y) if such a solution exists, otherwise None.

    Parameters:
    a (int): coefficient of x
    b (int): coefficient of y
    n (int): target integer

    Returns:
    Optional[Tuple[int, int]]: (x, y) with x >= 0, y >= 0 and a*x + b*y = n, or None if no solution.
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if b != 0 and n % b == 0 and (n // b >= 0):
            return (0, n // b)
        else:
            return None
    if b == 0:
        if a != 0 and n % a == 0 and (n // a >= 0):
            return (n // a, 0)
        else:
            return None
    max_x = n // a if a > 0 else 0
    if max_x < 0:
        max_x = 0
    for x in range(max_x + 1):
        remaining = n - a * x
        if b == 0:
            if remaining == 0:
                y = 0
                if y >= 0:
                    return (x, y)
        elif remaining % b == 0:
            y = remaining // b
            if y >= 0:
                return (x, y)
    return None

