from functools import lru_cache

def get_total_number_of_sequences(m: int, n: int) -> int:
    """
    Count sequences of length n with elements from 1 to m where each next element
    is at least twice the previous element.

    Args:
        m (int): Maximum allowed value in the sequence (elements in [1..m]).
        n (int): Length of the sequence.

    Returns:
        int: The total number of such sequences.
    """

    @lru_cache(None)
    def count_sequences(last: int, length: int) -> int:
        if length == n:
            return 1
        total = 0
        start = 2 * last
        for next_elem in range(start, m + 1):
            total += count_sequences(next_elem, length + 1)
        return total
    total_sequences = 0
    for first_elem in range(1, m + 1):
        total_sequences += count_sequences(first_elem, 1)
    return total_sequences

