def min_flip_to_make_string_alternate(s: str) -> int:
    """
    Compute the minimum number of bit flips needed to make the binary string strictly alternate.
    The cost is calculated for two possible alternating patterns:
    - starting with '0' (pattern: 0,1,0,1,...)
    - starting with '1' (pattern: 1,0,1,0,...)

    The function always returns the smaller of the two costs, which naturally covers the case
    when both costs are equal.

    Parameters:
    s (str): The input binary string

    Returns:
    int: The minimal number of flips to make the string strictly alternate.
    """
    cost_start_0 = 0
    cost_start_1 = 0
    for i, ch in enumerate(s):
        expected_0 = '0' if i % 2 == 0 else '1'
        expected_1 = '1' if i % 2 == 0 else '0'
        if ch != expected_0:
            cost_start_0 += 1
        if ch != expected_1:
            cost_start_1 += 1
    return min(cost_start_0, cost_start_1)

