from typing import List

def find_Max(arr: List[int], start: int, end: int) -> int:
    """
    Given a sorted and rotated array, this function finds the maximum element.

    Args:
        arr (List[int]): A sorted and rotated array
        start (int): Starting index of the subarray to search
        end (int): Ending index of the subarray to search

    Returns:
        int: The maximum element of the array
    """
    if start == end:
        return arr[start]
    if end == start + 1:
        return max(arr[start], arr[end])
    mid = (start + end) // 2
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    if arr[start] >= arr[mid]:
        return find_Max(arr, start, mid - 1)
    else:
        return find_Max(arr, mid + 1, end)
