from typing import List

def odd_length_sum(arr: List[int]) -> int:
    """
    Compute the sum of all odd length subarrays.

    This means we sum the elements of every subarray of odd length,
    and ignore subarrays of even length.

    Args:
        arr: List[int] - input array of integers

    Returns:
        int - the sum of all odd length subarrays
    """
    n = len(arr)
    total_sum = 0
    for start in range(n):
        for end in range(start, n):
            length = end - start + 1
            if length % 2 == 1:
                total_sum += sum(arr[start:end + 1])
    return total_sum

