def sum_column(data: List[List[float]], column_index: int) -> float:
    """
    Sums the specified column across all rows in the given list of lists.

    Parameters:
    data (List[List[float]]): A list of lists where each inner list represents a row of numerical values.
    column_index (int): The index of the column to sum.

    Returns:
    float: The sum of the specified column. If data is empty or no row has the specified column,
           returns 0.0.

    Notes:
    - Handles rows of varying lengths by summing only existent elements in the specified column.
    """
    total = 0.0
    for row in data:
        if column_index < len(row):
            total += row[column_index]
    return total

