from math import gcd
from typing import List

def get_gcd(arr: List[int]) -> int:
    """
    Finds the greatest common divisor (GCD) of all elements in the array.

    Args:
        arr (List[int]): A list of integers.

    Returns:
        int: The GCD of all elements in the input list, or 0 if the list is empty.
    """
    if not arr:
        return 0
    current_gcd = arr[0]
    for num in arr[1:]:
        current_gcd = gcd(current_gcd, num)
    return current_gcd

