def compute_Last_Digit(A: int, B: int) -> int:
    """
    Returns the last digit of the product of all integers from A+1 through B inclusive.
    If A == B, returns 1.
    If B - A >= 5, returns 0.

    Parameters:
    - A (int)
    - B (int)

    Returns:
    - int: last digit of the product as described.
    """
    if A == B:
        return 1
    if B - A >= 5:
        return 0
    product = 1
    for num in range(A + 1, B + 1):
        product *= num
    return abs(product) % 10

