def next_smallest_palindrome(num: int) -> int:
    """
    Given a number 'num', find the smallest palindrome strictly greater than 'num'.
    """

    def next_palindrome_str(s: str) -> str:
        length = len(s)
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            palindrome = left + left[::-1]
        else:
            palindrome = left + left[:-1][::-1]
        if palindrome > s:
            return palindrome
        left_as_num = int(left)
        left_as_num += 1
        left = str(left_as_num)
        if len(left) > half:
            return '1' + '0' * (length - 1) + '1'
        if length % 2 == 0:
            palindrome = left + left[::-1]
        else:
            palindrome = left + left[:-1][::-1]
        return palindrome
    s = str(num)
    if num < 9:
        return num + 1
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (len(s) - 1) + '1')
    next_pal = next_palindrome_str(s)
    return int(next_pal)

