def find_solution(a: int, b: int, n: int) -> Union[Tuple[int, int, int, int], str]:
    """
    Finds a non-negative integer solution (x, y) to the linear equation:
        a*x + b*y = n
    by scanning x starting at 0 upwards to find the first y that is an integer.

    Returns a 4-element tuple (a, b, x, y) if a solution exists,
    or the string "No solution" if none found.

    Note: Zero coefficients are not robustly handled and may cause errors or infinite loops.
    """
