    while True:
        rhs = n - a * x
        if b == 0:
            if a == 0:
                break
            if rhs == 0:
                return (a, b, x, 0)
            else:
                break
        if rhs % b == 0:
            y = rhs // b
            if y >= 0:
                return (a, b, x, y)
        x += 1
        if x > 10 ** 6:
            break
    return 'No solution'

