from typing import List, Union

def decode_list(compressed: List[Union[int, List[int]]]) -> List[int]:
    """
    Process a compressed list where each element is either an integer or a two-element list [count, value].
    If the element is an integer, it is added directly to the output list.
    If the element is a list [count, value], value is repeated count times in the output list.
    Tuples or other types are not handled and will raise a TypeError.

    Args:
        compressed: List of integers or two-element lists [count, value].

    Returns:
        List[int]: The decompressed list.

    Raises:
        TypeError: If an element is neither an int nor a two-element list.
        ValueError: If a two-element list does not contain exactly two integers.
    """
    result = []
    for element in compressed:
        if isinstance(element, list):
            if len(element) != 2:
                raise ValueError(f'List element must have exactly two integers: {element}')
            count, value = element
            if not (isinstance(count, int) and isinstance(value, int)):
                raise ValueError(f'Both count and value must be integers: {element}')
            result.extend([value] * count)
        elif isinstance(element, int):
            result.append(element)
        else:
            raise TypeError(f'Unsupported element type: {element} (type {type(element)})')
    return result

