from typing import Any

def remove_column(data: Any, key_to_remove: Any) -> Any:
    """
    Recursively remove all occurrences of key_to_remove from nested data structures.
    The data can be a dictionary, list of dicts, list of lists, or any nested combination thereof.

    Args:
        data: The nested data structure (dict, list, or other).
        key_to_remove: If data is dict, this is a string key to remove;
                       if data is a list of lists, this is an int index to remove from each inner list.

    Returns:
        A new data structure with the specified key or index removed wherever it occurs.
    """
    if isinstance(data, dict):
        return {k: remove_column(v, key_to_remove) for k, v in data.items() if k != key_to_remove}
    elif isinstance(data, list):
        if data and all((isinstance(item, list) for item in data)) and isinstance(key_to_remove, int):
            new_list = []
            for inner_list in data:
                if 0 <= key_to_remove < len(inner_list):
                    new_inner = inner_list[:key_to_remove] + inner_list[key_to_remove + 1:]
                else:
                    new_inner = inner_list[:]
                new_list.append(remove_column(new_inner, key_to_remove))
            return new_list
        else:
            return [remove_column(item, key_to_remove) for item in data]
    else:
        return data
