def highest_Power_of_2(value: int) -> int:
    """
    Find the highest power of 2 less than or equal to the given value.

    Args:
        value (int): The integer value to find the highest power of 2 for.

    Returns:
        int: The highest power of 2 less than or equal to value.
             Returns 0 if value is less than 1.
    """
    if value < 1:
        return 0
    power = 1
    while power <= value:
        power <<= 1
    return power >> 1

