def move_num(s):
    """
    Move all digit characters in the input string to the end of the string,
    preserving the order of both the non-digit and digit characters.

    Args:
        s (str): Input string possibly containing digits and other characters.

    Returns:
        str: String with all digits moved to the end in their original order.
    """
    non_digits = []
    digits = []
    for ch in s:
        if ch.isdigit():
            digits.append(ch)
        else:
            non_digits.append(ch)
    return ''.join(non_digits) + ''.join(digits)

