from typing import List

def odd_length_sum(arr: List[int]) -> int:
    """
    Calculate the sum of all subarrays of the input array that have an odd length.

    Parameters:
    arr (List[int]): The input list of integers.

    Returns:
    int: The sum of all odd-length subarrays.
    """
    total = 0
    n = len(arr)
    for start in range(n):
        for end in range(start, n):
            length = end - start + 1
            if length % 2 == 1:
                total += sum(arr[start:end + 1])
    return total

