from typing import Tuple, Union

def substract_elements(a: Tuple[Union[int, Tuple[int, ...]], ...], b: Tuple[Union[int, Tuple[int, ...]], ...]) -> Tuple:
    """
    Subtract elements of the second tuple from the first tuple element-wise,
    supporting nested tuples of integers. The subtraction is done up to the
    shorter length of the outer tuples and, if elements are tuples themselves,
    up to the shorter length of those inner tuples.

    Parameters:
    a (Tuple[Union[int, Tuple[int, ...]], ...]): The first tuple, possibly nested.
    b (Tuple[Union[int, Tuple[int, ...]], ...]): The second tuple, possibly nested.

    Returns:
    Tuple: A new tuple with element-wise subtractions. For nested tuples,
           each inner tuple is also subtracted element-wise up to the shorter length.

    Notes:
    - No error is raised if the tuples have different lengths; subtraction truncates
      to the shortest length.
    - Supports nested tuples of integers, not just flat tuples.
    """

    def subtract_inner(x, y):
        if isinstance(x, tuple) and isinstance(y, tuple):
            min_len = min(len(x), len(y))
            return tuple((x[i] - y[i] for i in range(min_len)))
        else:
            return x - y
    min_len = min(len(a), len(b))
    return tuple((subtract_inner(a[i], b[i]) for i in range(min_len)))

