def get_noOfways(n: int) -> int:
    """
    Returns the number of ways to tile a 2 x n board using 2 x 1 dominoes.

    According to the clarified specification:
    - get_noOfways(0) = 0
    - get_noOfways(1) = 1
    - get_noOfways(2) = 1
    - For n >= 3, get_noOfways(n) = get_noOfways(n-1) + get_noOfways(n-2)
    - Returns 0 for negative n

    Args:
        n (int): The length of the board.

    Returns:
        int: The number of ways to tile the 2 x n board.
    """
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 1
    prev, curr = (1, 1)
    for _ in range(3, n + 1):
        prev, curr = (curr, prev + curr)
    return curr

