def compute_Last_Digit(a: int, b: int) -> int:
    """
    Find the last digit of factorial(b) divided by factorial(a).

    This is equivalent to finding the last digit of the product of integers from (a+1) to b.

    Args:
        a (int): The smaller integer whose factorial divides factorial(b).
        b (int): The larger integer.

    Returns:
        int: The last digit of factorial(b) / factorial(a).

    Raises:
        ValueError: If a > b.
    """
    if a > b:
        raise ValueError('a must be less than or equal to b')
    if a == b:
        return 1
    product = 1
    for num in range(a + 1, b + 1):
