def next_smallest_palindrome(num: int) -> int:
    """
    Find the next smallest palindrome strictly greater than the given number.
    If no greater palindrome exists within a reasonable search range, return None.

    Args:
        num (int): The input number.

    Returns:
        int or None: The next smallest palindrome greater than num, or None if not found.
    """
    if num < 0:
        return None

