from typing import Optional, Tuple

def find_solution(a: int, b: int, n: int) -> Optional[Tuple[int, int]]:
    """
    Find one solution (x, y) with x, y >= 0 to the linear Diophantine equation:
        a*x + b*y = n

    If a nonnegative integer solution exists, return the one with the smallest nonnegative x found by incrementing x from 0 upwards.
    If no such solution exists, return None.
    """

    def extended_gcd(aa: int, bb: int) -> Tuple[int, int, int]:
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - aa // bb * y1
        return (gcd, x, y)
    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return None
    x0 *= n // gcd
    y0 *= n // gcd
    a_div = a // gcd
    b_div = b // gcd
    from math import ceil, floor
    k_min = ceil(-x0 / b_div) if b_div != 0 else 0
    k_max = floor(y0 / a_div) if a_div != 0 else 0
    if b_div == 0:
        if x0 < 0:
            return None
        if y0 < 0:
            return None
        return (x0, y0)
    if a_div == 0:
        if y0 < 0:
            return None
        if x0 < 0:
            return None
        return (x0, y0)
    if k_min > k_max:
        return None
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x < 0 or y < 0:
        return None
    return (x, y)

