from typing import List, Any

def decode_list(encoded: List[Any]) -> List[Any]:
    """
    Decode a run-length encoded list where the encoded input can contain
    either standalone values (representing single occurrences) or nested
    pairs [count, value] (representing repeated values).

    Args:
        encoded (List[Any]): The run-length encoded list, e.g.
            [ [3, 'a'], 'b', [2, 'c'], 'd' ]

    Returns:
        List[Any]: The decoded list with repeated values expanded.

    Examples:
        decode_list([[3, 'a'], 'b', [2, 'c'], 'd']) -> ['a', 'a', 'a', 'b', 'c', 'c', 'd']
        decode_list([]) -> []
        decode_list(['x', [2, 'y']]) -> ['x', 'y', 'y']
    """
    decoded = []
    for item in encoded:
        if isinstance(item, list):
            if len(item) != 2:
                raise ValueError(f'Invalid encoded pair {item}: must be length 2')
            count, value = item
            if not isinstance(count, int) or count < 0:
                raise ValueError(f'Count must be a non-negative integer, got {count}')
            decoded.extend([value] * count)
        else:
            decoded.append(item)
    return decoded

