def get_total_number_of_sequences(n: int, m: int) -> int:
    """
    Find the number of possible sequences of length n such that each next element is
    greater than or equal to twice the previous element but less than or equal to m.

    Parameters:
    n (int): The length of the sequence.
    m (int): The maximum allowed value for sequence elements.

    Returns:
    int: The total number of such sequences.
    """
    if n <= 0 or m <= 0:
        return 0
    dp = [dict() for _ in range(n + 1)]
    for v in range(1, m + 1):
        dp[1][v] = 1
    for length in range(2, n + 1):
        prev_dp = dp[length - 1]
        prefix = [0] * (m + 1)
        for val in range(1, m + 1):
            prefix[val] = prefix[val - 1] + prev_dp.get(val, 0)
        curr_dp = dp[length]
        for v in range(1, m + 1):
            max_prev = v // 2
            if max_prev >= 1:
                curr_dp[v] = prefix[max_prev]
            else:
                curr_dp[v] = 0
    return sum(dp[n].values())

