from typing import List, Any

def remove_column(matrix: List[List[Any]], col_index: int) -> List[List[Any]]:
    """
    Remove the column at index col_index from the given nested list (matrix).

    Args:
        matrix: A nested list representing the matrix.
        col_index: The index of the column to remove.

    Returns:
        A new nested list with the specified column removed.

    Raises:
        IndexError: If col_index is out of bounds for any row.

    Example:
        remove_column([[1,2,3],[4,5,6],[7,8,9]], 1) -> [[1,3],[4,6],[7,9]]
    """
    if not matrix:
        return []
    if col_index < 0 or col_index >= len(matrix[0]):
        raise IndexError(f'Column index {col_index} is out of bounds for the matrix columns')
    for row in matrix:
        if col_index >= len(row):
            raise IndexError(f'Column index {col_index} is out of bounds for row {row}')
    return [[row[i] for i in range(len(row)) if i != col_index] for row in matrix]

