from typing import List

def permute_string(s: str) -> List[str]:
    """
    Return a list of all permutations of the given string including duplicates.
    """
    result = []

    def backtrack(path: List[str], used: List[bool]):
        if len(path) == len(s):
            result.append(''.join(path))
            return
        for i in range(len(s)):
            if not used[i]:
                used[i] = True
                path.append(s[i])
                backtrack(path, used)
                path.pop()
                used[i] = False
    used = [False] * len(s)
    backtrack([], used)
    return result

