from typing import List

def find_Max(arr: List[int]) -> int:
    """
    Find the maximum element in a sorted and rotated array with distinct elements.

    Args:
        arr (List[int]): A non-empty sorted array that has been rotated, with distinct elements.

    Returns:
        int: The maximum element in the array.

    Raises:
        ValueError: If the input array is empty.

    Example:
        find_Max([4, 5, 6, 7, 0, 1, 2]) -> 7
    """
    if not arr:
        raise ValueError('Input array is empty')
    low, high = (0, len(arr) - 1)
    if arr[low] < arr[high]:
        return arr[high]
    while low <= high:
        mid = (low + high) // 2
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    return arr[0]

