from typing import List

def reverse_Array_Upto_K(arr: List[int], k: int) -> List[int]:
    """
    Reverse the array up to the given position k (1-based index).

    Parameters:
    arr (List[int]): The input array of integers.
    k (int): The position up to which to reverse the array (inclusive), 1-indexed.

    Returns:
    List[int]: The array with elements reversed up to position k.

    Example:
    >>> reverse_Array_Upto_K([1, 2, 3, 4, 5], 3)
    [3, 2, 1, 4, 5]
    """
