def check_subset(sub: tuple, full: tuple) -> bool:
    """
    Check if all unique elements in 'sub' tuple appear at least once in 'full' tuple,
    ignoring order and duplicates.

    The empty tuple is a subset of any tuple;
    no non-empty tuple is a subset of an empty tuple.

    Args:
        sub (tuple): Candidate subset tuple.
        full (tuple): Candidate superset tuple.

    Returns:
        bool: True if 'sub' is a subset of 'full', False otherwise.
    """
    if not sub:
