def odd_length_sum(arr):
    """
    Calculate the sum of all subarrays of arr that have an odd length.

    Parameters:
    arr (list of int): The input array of integers.

    Returns:
    int: The sum of all odd-length subarrays.
    """
    total = 0
    n = len(arr)
    for start in range(n):
        for length in range(1, n - start + 1, 2):
            subarray_sum = sum(arr[start:start + length])
            total += subarray_sum
    return total

