from typing import Tuple, Union
NestedTuple = Union[int, Tuple['NestedTuple', ...]]

def substract_elements(t1: NestedTuple, t2: NestedTuple) -> int:
    """
    Subtract elements between two nested tuples or ints.

    The subtraction is performed by:
    - Recursively computing the integer value for each input (if int, use directly;
      if tuple, subtract all subsequent elements from the first element recursively).
    - Then subtracting the second computed value from the first.

    Examples:
    >>> substract_elements(5, 3)
    2
    >>> substract_elements((10, 3, 2), (1, 1))
    3  # (10 - 3 - 2) - (1 - 1) = 5 - 0 = 5
    >>> substract_elements((10, (3, 1), 2), 4)
    0  # (10 - (3-1) - 2) - 4 = (10 - 2 - 2) - 4 = 6 - 4 = 2
    >>> substract_elements(((20, 5), 3, (2, 1)), (5, 2))
    2  # ( (20 - 5) - 3 - (2 - 1) ) - (5 - 2) = (15 - 3 - 1) - 3 = 11 - 3 = 8
    """

    def eval_nested(t: NestedTuple) -> int:
        if isinstance(t, int):
            return t
        elif isinstance(t, tuple):
            if not t:
                return 0
            result = eval_nested(t[0])
            for elem in t[1:]:
                result -= eval_nested(elem)
            return result
        else:
            raise TypeError('Input must be an int or nested tuple of ints')
    return eval_nested(t1) - eval_nested(t2)

