def lucky_num(n: int) -> list[int]:
    lucky = list(range(1, 2 * n * 10, 2))
    idx = 1
    while idx < len(lucky):
        step = lucky[idx]
        if step > len(lucky):
            break
        lucky = [lucky[i] for i in range(len(lucky)) if (i + 1) % step != 0]
        idx += 1
        if len(lucky) >= n:
            pass
    return lucky[:n]

