import math

def dif_Square(n: int) -> bool:
    """
    Check if the integer n can be represented as the difference of squares of two integers.
    That is, check if there exist integers a, b such that n = a^2 - b^2.

    Since a^2 - b^2 = (a-b)(a+b), the problem reduces to checking if n can be factored
    into two integers x and y (x = a-b, y = a+b) with the same parity and y > x > 0.

    Args:
        n (int): The integer to check.

    Returns:
        bool: True if n can be represented as difference of squares, False otherwise.
    """
    abs_n = abs(n)
    if n == 0:
        return True
    for x in range(1, int(math.isqrt(abs_n)) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            if (x + y) % 2 == 0 and y > x:
                a = (y + x) // 2
                b = (y - x) // 2
                if a * a - b * b == n or b * b - a * a == n:
                    return True
    return False

