def next_smallest_palindrome(num: int) -> int:
    """
    Find the next smallest palindrome number strictly less than the given number.

    Parameters:
    num (int): The number to find the next smallest palindrome for.

    Returns:
    int: The next smallest palindrome less than num.
         If no smaller palindrome exists (e.g., for num <= 0 or num == 1), return None.
    """
    if num <= 0:
        return None
    if num == 1:
        return 0

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]
    candidate = num - 1
    while candidate >= 0:
        if is_palindrome(candidate):
            return candidate
        candidate -= 1
    return None

