def find_solution(a: int, b: int, n: int):
    """
    Find one pair of integers (x, y) such that a*x + b*y = n, with x >= 0 if possible.
    If no solution exists, return the string 'No solution'.

    This function uses the Extended Euclidean algorithm to find one particular solution,
    then searches for the first solution with non-negative x by scanning upward from x=0.

    Parameters:
    a (int): coefficient of x
    b (int): coefficient of y
    n (int): target integer

    Returns:
    tuple or str: a labeled tuple ('x = ', x, ', y = ', y) that satisfies the equation,
                  or the string 'No solution' if no solution exists.
    """

    def extended_gcd(aa, bb):
        """Return (g, x, y) such that aa*x + bb*y = g = gcd(aa, bb)"""
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - aa // bb * y1
            return (g, x, y)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'
    x0 *= n // g
    y0 *= n // g
    b_div_g = b // g
    a_div_g = a // g
    if b_div_g == 0:
        if x0 >= 0:
            return ('x = ', x0, ', y = ', y0)
        else:
            return 'No solution'
    from math import ceil
    k = ceil(-x0 / b_div_g)
    x = x0 + k * b_div_g
    y = y0 - k * a_div_g
    return ('x = ', x, ', y = ', y)

