def next_power_of_2(n: int) -> int:
    """
    Find the smallest power of 2 that is at least n.

    Args:
        n (int): The input integer.

    Returns:
        int: The smallest power of 2 greater than or equal to n.
             For n <= 1 (including zero and negative), returns 1.
    """
    if n <= 1:
        return 1
    if n & n - 1 == 0:
        return n
    power = 1
    while power < n:
