from typing import List, Any, Union

def decode_list(encoded: List[Union[List[Any], Any]]) -> List[Any]:
    """
    Decode a run-length encoded list.

    Each element in the input list is either:
    - a pair [count, value], where 'count' is the number of times 'value' is repeated, or
    - a single value, which should be included once in the output.

    Args:
        encoded: A list containing either [count, value] pairs or single values.

    Returns:
        A decoded list with values repeated count times, or single values included once.
    """
    result = []
    for item in encoded:
        if isinstance(item, list) and len(item) == 2:
            count, value = item
            result.extend([value] * count)
        else:
            result.append(item)
    return result

