from functools import lru_cache

def get_total_number_of_sequences(m: int, n: int) -> int:
    """
    Count the number of possible lists of length n such that each successive element
    is at least twice the previous element but does not exceed m.

    Interpretation:
    - The sequence elements are positive integers.
    - For each successive pair (a[i], a[i+1]), a[i+1] >= 2 * a[i].
    - Each element <= m.

    Parameters:
    - m: maximum allowed value for elements
    - n: length of the sequence

    Returns:
    - count of such sequences
    """
    if n == 0:
        return 0
    if n == 1:
        return m

    @lru_cache(None)
    def count_sequences(length: int, prev: int) -> int:
        if length == n:
            return 1
        total = 0
        start = 2 * prev
        for nxt in range(start, m + 1):
            total += count_sequences(length + 1, nxt)
        return total
    total_sequences = 0
    for first_elem in range(1, m + 1):
        total_sequences += count_sequences(1, first_elem)
    return total_sequences

