def min_flip_to_make_string_alternate(s: str) -> int:
    """
    Given a binary string s, returns the minimum number of flips required to make the string 
    alternate (i.e., no two adjacent characters are the same). The string can be made alternating
    starting with either '0' or '1'.

    Args:
        s (str): binary string consisting of '0's and '1's.

    Returns:
        int: minimum flips required to make the string alternate.
    """
    flips_start_with_0 = 0
    flips_start_with_1 = 0
    for i, ch in enumerate(s):
        expected_char_0 = '0' if i % 2 == 0 else '1'
        expected_char_1 = '1' if i % 2 == 0 else '0'
        if ch != expected_char_0:
            flips_start_with_0 += 1
        if ch != expected_char_1:
            flips_start_with_1 += 1
    return min(flips_start_with_0, flips_start_with_1)

