    """
    Identify the highest power of 2 that is less than or equal to n.

    Parameters:
    n (int): A positive integer or zero.

    Returns:
    int: The highest power of 2 less than or equal to n.
         If n is less than 1, returns 0 as no positive power of 2 is <= n.
    """
    if n < 1:
        return 0
    power = 1
    while power <= n:
