from collections.abc import Collection

def check_subset(container: Collection, contained: Collection) -> bool:
    """
    Check if all elements of 'contained' are present in 'container'.

    Args:
        container (Collection): The collection to be checked against.
        contained (Collection): The collection to check whether it is contained within 'container'.

    Returns:
        bool: True if every element of 'contained' is in 'container', False otherwise.
    """
    try:
        return set(contained).issubset(container)
    except TypeError:
        container_list = list(container)
        for item in contained:
            if item not in container_list:
                return False
        return True
