def lucky_num(n):
    """
    Generate the first n lucky numbers.

    Lucky numbers are generated by a sieve:
    1. Start with the list of numbers: 1 followed by odd numbers (1, 3, 5, 7, 9, ...).
    2. The first number in the list (1) is a lucky number.
    3. Remove every step-th number where step is the current lucky number (starting from the step-th element in the list).
    4. Repeat step 3 with the next lucky number until at least n lucky numbers are generated.

    Parameters:
        n (int): The number of lucky numbers to generate.

    Returns:
        list[int]: A list containing the first n lucky numbers.
    """
    if n < 1:
        return []
    estimate = max(10, n * 20)
    while True:
        numbers = [1] + list(range(3, estimate * 2, 2))
        idx = 1
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            del numbers[step - 1::step]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        estimate *= 2

