def next_smallest_palindrome(num: int) -> int:
    """
    Returns the smallest palindrome strictly greater than num.
    If num consists of all 9s, returns the next palindrome after num.
    """
    s = str(num)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return num + 2

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            pal = left + left[-2::-1]
        else:
            pal = left + left[::-1]
        return int(pal)

    def increment_str_num(s_num: str) -> str:
        num_int = int(s_num) + 1
        return str(num_int)
    odd_length = length % 2 != 0
    left_half = s[:(length + 1) // 2]
    p = make_palindrome(left_half, odd_length)
    if p > num:
        return p
    left_half_inc = increment_str_num(left_half)
    if len(left_half_inc) > len(left_half):
        if odd_length:
            return int(left_half_inc + left_half_inc[-2::-1])
        else:
            return int(left_half_inc + left_half_inc[::-1])
    else:
        return make_palindrome(left_half_inc, odd_length)

