from typing import Optional, Tuple, Union

def find_solution(a: int, b: int, n: int) -> Union[Tuple[int, int], str]:
    """
    Find the first pair of integers (x, y) with x >= 0 such that a*x + b*y = n.
    Scans non-negative x upward from 0, checking if y = (n - a*x) / b is an integer.
    If no such solution exists, returns the string 'No solution'.
    """
    if b == 0:
        if a == 0:
            return (0, 0) if n == 0 else 'No solution'
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return 'No solution'
    if a == 0:
        if n % b == 0:
            return (0, n // b)
        else:
            return 'No solution'
    max_x = abs(n) + abs(b) + 1
    for x in range(max_x):
        numerator = n - a * x
        if numerator % b == 0:
            y = numerator // b
            return (x, y)
    return 'No solution'

