def next_power_of_2(n: int) -> int:
    """
    Find the smallest power of 2 greater than or equal to n.

    Args:
        n (int): The input integer.

    Returns:
        int: The smallest power of 2 >= n if n >= 0; 
             for negative n, returns 1 as a fallback.

    Examples:
        >>> next_power_of_2(5)
        8
        >>> next_power_of_2(16)
        16
        >>> next_power_of_2(0)
        1
        >>> next_power_of_2(-3)
        1
    """
    if n == 0:
        return 1
    if n < 0:
        return 1
    if n & n - 1 == 0:
        return n
    power = 1
    while power < n:
        power <<= 1
    return power

