from typing import List, Union

def decode_list(encoded: List[Union[int, List[int]]]) -> List[int]:
    """
    Decodes a run-length encoded list.

    The input list can contain a mix of individual values and [count, value] pairs.
    - If an element is an integer, it represents a single occurrence of that value.
    - If an element is a list [count, value], it represents 'count' occurrences of 'value'.

    Parameters:
    encoded (List[Union[int, List[int]]]): The run-length encoded list.

    Returns:
    List[int]: The decoded list.
    """
    decoded = []
    for item in encoded:
        if isinstance(item, list) and len(item) == 2:
            count, value = item
            decoded.extend([value] * count)
        else:
            decoded.append(item)
    return decoded

