import re

def text_match_two_three(text: str) -> str:
    """
    Returns "Found a match!" if the input string contains an 'a' followed immediately
    by exactly two or three 'b's anywhere in the string.
    Otherwise, returns "Not matched!".

    Examples:
    - text_match_two_three("abb") -> "Found a match!"
    - text_match_two_three("abbb") -> "Found a match!"
    - text_match_two_three("ab") -> "Not matched!"
    - text_match_two_three("abbbb") -> "Not matched!"
    """
    pattern = 'ab{2,3}'
    if re.search(pattern, text):
        pattern_exact = 'a(b{2,3})(?!b)'
        if re.search(pattern_exact, text):
            return 'Found a match!'
    return 'Not matched!'

