from typing import List

def smallest_missing(arr: List[int], left: int, right: int) -> int:
    """
    Finds the smallest missing non-negative integer in a sorted array of integers.

    The array may contain duplicates and negative numbers.
    The function uses a binary search approach comparing element values to indices.

    Args:
        arr: A sorted list of integers.
        left: Left index for the current search range.
        right: Right index for the current search range.

    Returns:
        The smallest missing non-negative integer.
    """
    if left > right:
        return left
    mid = (left + right) // 2
    if arr[mid] < 0 or arr[mid] > mid:
        return smallest_missing(arr, left, mid - 1)
    elif arr[mid] == mid:
        return smallest_missing(arr, mid + 1, right)
    else:
        return smallest_missing(arr, left, mid - 1)
