from typing import List

def permute_string(s: str) -> List[str]:
    """
    Return a list of all unique permutations of the given string s.
    """
    results = []
    chars = sorted(s)
    used = [False] * len(s)

    def backtrack(path: List[str]):
        if len(path) == len(chars):
            results.append(''.join(path))
            return
        for i in range(len(chars)):
            if used[i]:
                continue
            if i > 0 and chars[i] == chars[i - 1] and (not used[i - 1]):
                continue
            used[i] = True
            path.append(chars[i])
            backtrack(path)
            path.pop()
            used[i] = False
    backtrack([])
    return results

