from typing import List

def find_remainder(arr: List[int], n: int) -> int:
    """
    Returns the remainder of the product of all elements in arr divided by n.

    Parameters:
    arr (List[int]): List of integers to multiply.
    n (int): The divisor.

    Returns:
    int: The remainder of the product modulo n.

    Raises:
    ZeroDivisionError: If n is zero.
    """
    if n == 0:
        raise ZeroDivisionError('Divisor n cannot be zero.')
    product_mod = 1
    for num in arr:
        product_mod = product_mod * (num % n) % n
    return product_mod

