from typing import List

def find_Max(arr: List[int], low: int, high: int) -> int:
    """
    Finds the maximum element in a sorted and rotated array.

    Args:
        arr (List[int]): A list of integers sorted and then rotated.
        low (int): Starting index of the segment to search.
        high (int): Ending index of the segment to search.

    Returns:
        int: The maximum element in the array segment.

    Raises:
        ValueError: If the input array segment is empty or indices are invalid.
    """
    if not arr or low > high or low < 0 or (high >= len(arr)):
        raise ValueError('Invalid input: array must be non-empty and indices valid')
    if arr[low] <= arr[high]:
        return arr[high]
    while low <= high:
        mid = (low + high) // 2
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    return arr[0]

