def move_num(s: str) -> str:
    """
    Move all the numbers in the input string to the end, preserving the order of the non-numeric
    characters and the numeric characters.

    Args:
        s: The input string.

    Returns:
        A string with all numbers moved to the end.

    Examples:
        move_num("a1b2c3") -> "abc123"
        move_num("123abc") -> "abc123"
        move_num("abc") -> "abc"
        move_num("123") -> "123"
    """
    letters = []
    digits = []
    for ch in s:
        if ch.isdigit():
            digits.append(ch)
        else:
            letters.append(ch)
    return ''.join(letters) + ''.join(digits)

