from typing import List

def odd_length_sum(arr: List[int]) -> int:
    """
    Return the sum of all odd length subarrays of the given array.

    A subarray is defined as a contiguous part of the array.

    Parameters:
    arr (List[int]): The input array of integers.

    Returns:
    int: The sum of all odd length subarrays.
    """
    total_sum = 0
    n = len(arr)
    for length in range(1, n + 1, 2):
        for start in range(n - length + 1):
            total_sum += sum(arr[start:start + length])
    return total_sum

