    Note: The function should work for all real numbers, not just integers. 

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """

    def max_depth(paren_group: str) -> int:
        from functools import reduce

        def reducer(acc, ch):
            curr, maximum = acc
            if ch == '(':
                curr += 1
                maximum = max(maximum, curr)
            elif ch == ')':
                curr -= 1
            return (curr, maximum)
        _, depth = reduce(reducer, paren_group, (0, 0))
        return depth
    groups = paren_string.split()
    depths = list(map(max_depth, groups))
    return depths

