def decode_shift(s: str) -> str:
    """
    Takes as input string encoded with encode_shift function. Returns decoded string.
    The encode_shift function shifts every character by 5 in the alphabet unless the string only consists of numerals,
    in which case it returns the reversed string.

    This decode_shift function reverses that operation and returns the decoded string (never as an integer).

    Steps:
    - If the input string consists only of digits, it means it was reversed from a numeral string.
      So reverse it again and return as string.
    - Otherwise, the string was encoded by shifting letters by +5.
      To decode, shift letters by -5.
      Return the decoded string.
    """
    if s.isdigit():
        return s[::-1]
    else:
        decoded_chars = []
        for ch in s:
            if 'a' <= ch <= 'z':
                decoded_char = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
                decoded_chars.append(decoded_char)
            else:
                decoded_chars.append(ch)
        decoded_str = ''.join(decoded_chars)
        return decoded_str

