def monotonic(l: Union[list, str]) -> Union[Tuple[bool, Union[int, str]], bool]:
    """
    For a list input:
        Return (True, sum_of_elements) if elements are strictly increasing or strictly decreasing with no duplicates.
        Return False otherwise.
    For a string input:
