def select_words(s, n):
    """
    Given a string s and a natural number n, returns a list of all words from s that contain exactly n consonants,
    preserving their original order.
    If s is empty, returns an empty list.
    The function must not use any loops and must have O(1) complexity (interpreted as using recursion or comprehensions).
    The function works for strings only.
    """
    if not s:
        return []
    vowels = set('aeiouAEIOU')
    words = s.split()

    def consonant_count(word):
        if not word:
            return 0
        first = word[0]
        first_is_consonant = first.isalpha() and first not in vowels
        return (1 if first_is_consonant else 0) + consonant_count(word[1:])
    filtered_words = list(filter(lambda w: consonant_count(w) == n, words))
    return filtered_words

