from typing import List, Union

def order_by_points(nums: List[Union[int, str]]) -> List[Union[int, str]]:
    """
    Sort the given list of integers and strings representing numbers in ascending order 
    according to the sum of their digits, where for negative numbers the sign applies 
    only to the first digit and the rest digits are summed as positive. In case of ties,
    preserve the original order. Return the sorted list (not a string). For empty input,
    return an empty list. This function uses no loops or recursion.

    Example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """

    def digit_sum(x):
        s = str(x)
        if s.startswith('-') and len(s) > 1:
            first_digit = -int(s[1])
            rest_digits = map(int, s[2:])
            return first_digit + sum(rest_digits)
        else:
            return sum(map(int, filter(str.isdigit, s)))
    return sorted(nums, key=digit_sum)

