from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input to this function is a string representing multiple groups for nested parentheses separated by spaces.
    For each group, output an integer representing the maximum depth of nested parentheses in that group.

    The groups are separated by space characters only.

    Example:
        Input: "(()) (())() ((()))"
        Groups: "(())", "(())()", "((()))"
        Output: [2, 2, 3]
    """
    results = []
    groups = paren_string.split(' ') if ' ' in paren_string else [paren_string]
    for group in groups:
