def max_depth(group: str) -> int:
    """
    Compute the maximum depth of nested parentheses in a string containing only '(' and ')'.
    Return 0 if parentheses are unbalanced.
    """
    max_d = 0
    current_d = 0
    for ch in group:
        if ch == '(':
            current_d += 1
            max_d = max(max_d, current_d)
        elif ch == ')':
            current_d -= 1
            if current_d < 0:
                return 0
        else:
            return 0
    if current_d != 0:
        return 0
    return max_d

