def digits(n):
    """
    Given a positive integer n, return the product of its odd digits.
    If there are no odd digits, return 0.
    For example, digits(54) returns 5 because 5 is the only odd digit.
    """
    digits_list = [int(d) for d in str(n)]
    odd_digits = [d for d in digits_list if d % 2 == 1]
    if not odd_digits:
        return 0
    product_odd = 1
    for d in odd_digits:
        product_odd *= d
    return product_odd

