def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    Only lowercase alphabetic characters are shifted; other characters are unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) + 5 - ord('a')) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    Only lowercase alphabetic characters are shifted backward by 5 with wrap-around;
    other characters are preserved unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - 5 - ord('a')) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)

