def select_words(s, n):
    """
    Given a string s and a natural number n, returns a list of all words from string s
    that contain exactly n consonants, in the order these words appear in s.
    If s is empty, returns an empty list.
    Assumes s contains only letters and spaces.
    """
    if not s:
        return []
    vowels = set('aeiouAEIOU')
    words = s.split()
    result = []
    for word in words:
        consonant_count = sum((1 for ch in word if ch.isalpha() and ch not in vowels))
        if consonant_count == n:
            result.append(word)
    return result

