from typing import List

def order_by_points(nums: List[int]) -> List[int]:
    """
    Write a function which sorts the given list of integers
    in descending order according to the sum of their digits,
    where for negative numbers only the first digit after the minus sign is negated.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list (stable sort).

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """

    def digit_sum(n: int) -> int:
        s = str(n)
        if s[0] == '-':
            first_digit = -int(s[1])
            rest_digits = sum((int(d) for d in s[2:]))
            return first_digit + rest_digits
        else:
            return sum((int(d) for d in s))
    return sorted(nums, key=digit_sum, reverse=True)

