def parse_nested_parens(s: str) -> list[int]:
    """
    Given a string containing multiple groups of parentheses separated by spaces,
    return a list of the deepest level of nesting for each group.

    Example:
    parse_nested_parens('(()()) ((())) () ((())()())') -> [2, 3, 1, 3]

    Any random characters inside groups are ignored for nesting calculation.

    Args:
        s (str): input string with groups separated by spaces

    Returns:
        list[int]: list of maximum nesting depths for each group
    """
    groups = s.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

