def circular_shift(x: int, y: int) -> str:
    """
    Circularly shift the digits of x to the right by y positions.

    If y is larger than or equal to the number of digits in x,
    the output should be the digits of x reversed as a string.

    Examples:
    circular_shift(12, 1) -> "21"
    circular_shift(12, 2) -> "21" reversed -> "21" reversed is "12"
    """
    s = str(x)
    n = len(s)
    if y >= n:
        return s[::-1]
    return s[-y:] + s[:-y]

