def prime_length(s: str) -> bool:
    """
    Determine if the length of the input string s is a prime number.

    Args:
        s (str): Input string.

    Returns:
        bool: True if the length of s is prime, False otherwise.
    """
    n = len(s)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(n ** 0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True

