from typing import List

def order_by_points(numbers: List[int]) -> List[int]:
    """
    Takes a list of integers (which may be negative) and returns a new list ordered by the sum of their digits,
    where for negative numbers the leading minus sign makes the first digit negative.
    If two numbers have the same sum of digits, their original order is preserved.
    """

    def sum_of_digits(n: int) -> int:
        s = str(n)
        total = 0
        i = 0
        if s[0] == '-':
            total += -int(s[1])
            i = 2
        else:
            total += int(s[0])
            i = 1
        for c in s[i:]:
            total += int(c)
        return total
    return sorted(numbers, key=sum_of_digits)

