def monotonic(seq: Sequence[float]) -> bool:
    """
    Return True if sequence items broadly move in one direction.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(seq) < 2:
        return True
    increasing = decreasing = True
    for i in range(1, len(seq)):
        if seq[i] > seq[i - 1]:
            decreasing = False
        elif seq[i] < seq[i - 1]:
            increasing = False
    return increasing or decreasing

