def prime_length(item):
    """Create a small routine that accepts some text and indicates a truthy result
    when its overall size is a prime number, and a falsy one otherwise.

    Examples
    --------
    prime_length('Hello') == True
    prime_length('abcdcba') == True
    prime_length('kittens') == True
    prime_length('orange') == False
    """

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True
    return is_prime(len(item))

