def anti_shuffle(t: str) -> str:
    """
    Make a routine that accepts some text and yields a more ordered form.
    The ordered form of the text is a version where all words (separated by space)
    are swapped out for a new word where the characters are put in
    a simple ascending arrangement based on underlying character codes.
    Note: You should keep the order of words and blank spaces in the sentence.

    For example:
    anti_shuffle('Hi') returns 'Hi'
    anti_shuffle('hello') returns 'ehllo'
    anti_shuffle('Hello World!!!') returns 'Hello !!!Wdlor'
    """
    tokens = []
    current = []
    for ch in t:
        if ch == ' ':
            if current and current[-1] != ' ':
                tokens.append(''.join(current))
                current = []
            current.append(ch)
        else:
            if current and current[-1] == ' ':
                tokens.append(''.join(current))
                current = []
            current.append(ch)
    if current:
        tokens.append(''.join(current))
    result_tokens = []
    for token in tokens:
        if all((ch == ' ' for ch in token)):
            result_tokens.append(token)
            continue
        sorted_token = ''.join(sorted(token))
        result_tokens.append(sorted_token)
    return ''.join(result_tokens)

