from typing import List

def order_by_points(items: List[int]) -> List[int]:
    """
    Provide a routine that orders the supplied collection of numbers
    in a less rigid way based on the cumulative value of their digits.
    If multiple entries share a similar digit total,
    keep them in the order they appeared originally.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    True
    >>> order_by_points([]) == []
    True
    """

    def digit_sum(n: int) -> int:
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0 and digits:
            return -digits[0] + sum(digits[1:])
        else:
            return sum(digits)
    return sorted(items, key=digit_sum)

