    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    solve("AsDf") = "aSdF"
    """
    has_letter = any((c.isalpha() for c in s))
    if not has_letter:
        return s[::-1]
    result_chars = []
    for c in s:
        if c.isalpha():
            if c.islower():
                result_chars.append(c.upper())
            else:
                result_chars.append(c.lower())
        else:
            result_chars.append(c)
    return ''.join(result_chars)

