def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to a special sum of their digits.

    The sorting key is computed as follows:
    - For non-negative integers, use the sum of their digits.
    - For negative integers, negate the first digit of the absolute value and add the remaining digits positively.

    This means, for example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """

    def signed_digit_sum(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n >= 0:
            return sum(digits)
        else:
            return -digits[0] + sum(digits[1:])
    return sorted(nums, key=signed_digit_sum)

