def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string representing multiple groups of nested parentheses separated by spaces.
    For each group, output an integer representing the maximum nesting depth of parentheses in that group.
    """

    def max_depth(paren_group: str) -> int:
        depth = 0
        max_depth = 0
        for ch in paren_group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
                if depth < 0:
                    depth = 0
        return max_depth
    groups = paren_string.split()
    return [max_depth(group) for group in groups]

