    """
    Input to this function is a string representing musical notes in a special ASCII format.
    Your task is to parse this string and return list of integers corresponding to how many beats 
    does each note last.

    The input is a single string of space-separated note tokens.
    The beats are not counted by repeated characters but by exact token matches:
      "o"  means 4 beats,
      "o|" means 2 beats,
      ".|" means 1 beat.

    For example, "o o o o" returns [4, 4, 4, 4].

    Notes not matching these tokens will raise a ValueError.
    """
    if not music_string.strip():
        return []
    token_to_beats = {'o': 4, 'o|': 2, '.|': 1}
    notes = music_string.strip().split()
    beats = []
    for note in notes:
        if note not in token_to_beats:
            raise ValueError(f'Unknown note token: {note}')
        beats.append(token_to_beats[note])
    return beats

