from typing import List

def smallest_change(arr: List[int]) -> int:
    """
    Given an array arr of integers, find the number of elements that
    need to be changed to make the array palindromic. A palindromic array is an array that
    is read the same backwards and forwards. In one change, you can change one element to any other element.

    The minimal number of changes equals the count of pairs of symmetric elements that differ,
    since changing one element in each such pair suffices.
    """
    n = len(arr)
    changes = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

