def sum_squares(lst):
    """
    This function will take a list of integers. The function will not 
    change the entries in the list whose indexes are not a multiple of 3 or 4.
    Instead, it will:
    - square elements at indexes divisible by 3,
    - cube elements at indexes divisible by 4 but not by 3,
    - leave all other elements unchanged.
    The function shall then return the sum of all entries. 

    Examples:
    For lst = [1,2,3] the output should be 6  # index 0 squared (1^2=1), index 1 unchanged, index 2 unchanged -> sum=1+2+3=6
    For lst = [] the output should be 0
    For lst = [-1,-5,2,-1,-5] the output should be -126
    For lst = [-1,-1,-1,-1,-1,-1,-1,-1,-1] the output should be -3
    """
    modified_lst = lst[:]
    for i in range(len(modified_lst)):
        if i % 3 == 0:
            modified_lst[i] = modified_lst[i] ** 2
        elif i % 4 == 0:
            modified_lst[i] = modified_lst[i] ** 3
    return sum(modified_lst)

