def parse_nested_parens(paren_string):
    """ Input to this function is a string containing one or more groups of parentheses separated by spaces.
        Output is a list of integers representing the deepest level of nesting of parentheses in each group.
    """
    results = []
    groups = paren_string.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                if current_depth > 0:
                    current_depth -= 1
                else:
                    pass
        results.append(max_depth)
    return results

