def parse_music(notes: str) -> list[int]:
    """
    Parse a string representing musical notes and return a list of integers corresponding to how many beats each note lasts.

    Legend:
    'o'  - whole note, lasts four beats
    'o|' - half note, lasts two beats
    '.|' - quarter note, lasts one beat

    Parameters:
    notes (str): The input string containing notes separated by spaces.

    Returns:
    list[int]: A list of integers representing beats for each note.
    """
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    result = []
    tokens = notes.split()
    for token in tokens:
        if token in beats_map:
            result.append(beats_map[token])
    return result

