def order_by_points(nums):
    """
    Write a function which sorts the given list of integers in ascending order
    according to the sum of their digits, where for negative integers the first
    digit is negated before summing.

    For example, -12 has a digit sum of (-1) + 2 = 1, distinguishing it from
    simply summing absolute digits.
    """

    def digit_sum(n):
        s = str(abs(n))
        digits = [int(d) for d in s]
        if n < 0:
            digits[0] = -digits[0]
        return sum(digits)
    return sorted(nums, key=digit_sum)

