from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input to this function is a string representing multiple groups of nested parentheses separated by spaces.
    For each space-separated group, output the deepest level of nesting of parentheses.
    E.g. '(()()) ((())) () ((())()())' has maximum depths [2, 3, 1, 3].

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    depths = []
    groups = paren_string.split()
    for group in groups:
        current_depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths

