def prime_length(string: str) -> bool:
    """Write a function that takes a string and returns True if the string
    length is a prime number, or False otherwise.

    Examples
    prime_length('Hello') == False     # length 5, prime? True, so this example would be True
    prime_length('abcdcba') == False   # length 7, prime? True, so this example would be True
    prime_length('kittens') == False   # length 7, prime? True, so this example would be True
    prime_length('orange') == False    # length 6, prime? False
    prime_length('apple') == True      # length 5, prime? True
    """
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return False
    return True

