def sum_squares(lst):
    """
    This function will take a list of integers. For all entries in the list, the function shall square the integer entry if its index is a
    multiple of 3 (including those that are multiples of both 3 and 4) and will cube the integer entry if its index is a multiple of 4 and not a multiple of 3.
    The function will not change the entries in the list whose indexes are not a multiple of 3 or 4. The function shall then return the sum of all entries.

    Examples:
    For lst = [1,2,3] the output should be 14
    For lst = [] the output should be 0
    For lst = [-1,-5,2,-1,-5] the output should be 20
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            transformed = val ** 2
        elif i % 4 == 0:
            transformed = val ** 3
        else:
            transformed = val
        total += transformed
    return total

