from typing import List

def order_by_points(nums: List[int]) -> List[int]:
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits,
    where the sum for negative numbers treats the leading '-' as a negative sign applied only to the first digit 
    (e.g., -12 as -1 + 2 = 1), not as sum of absolute digits.
    If there are several items with similar sum of their digits,
    order them based on their index in original list (stable sort).

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [1, -1, 11, -11, -12]
    >>> order_by_points([]) == []
    """

    def digit_sum(n: int) -> int:
        s = str(n)
        if s[0] == '-':
            return -int(s[1]) + sum((int(d) for d in s[2:]))
        else:
            return sum((int(d) for d in s))
    return sorted(nums, key=digit_sum)

